// カード歴史: every balance patch, newest first. Card snapshots are what the card said
// before / after that patch (built from scripts/carddump.ts + scripts/patchdiff.mjs).
import type { ClassId } from '../engine';

export type ChangeKind = 'buff' | 'nerf' | 'adjust' | 'rework';

export interface CardSnap {
  cost: number;
  atk?: number;
  hp?: number;
  countdown?: number;
  kw?: string[];
  text: string;
}

export interface PatchChange {
  id: string;
  name: string;
  cls: ClassId;
  kind: ChangeKind;
  before: CardSnap;
  after: CardSnap;
}

export interface Patch {
  id: string;
  date: string;
  title: string;
  summary: string;
  changes: PatchChange[];
  added: { name: string; cls: ClassId }[];
  rules: string[];
}

